const exec = $json.execution || {};
const callbackId = exec.customData?.callbackId || '';
const lastNode = exec.lastNodeExecuted || 'desconhecido';
const errorMsg = exec.error?.message || 'Erro desconhecido no n8n';

return [{
  json: {
    callbackId,
    errorMessage: 'Erro em "' + lastNode + '": ' + errorMsg
  }
}];
